import React, { useState, useMemo, useEffect } from "react";
import "./InformeInteractivo.css";
import {
  Table,
  Input,
  Select,
  Card,
  Row,
  Col,
  Progress,
  Statistic,
  Typography,
  Divider,
} from "antd";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  ComposedChart,
  Line,
  ReferenceLine,
} from "recharts";

import {
  CarOutlined,
  UserOutlined,
  TeamOutlined,
  RiseOutlined,
  AlertOutlined,
  BarChartOutlined,
  DollarOutlined,
  FundOutlined,
} from "@ant-design/icons";
import * as XLSX from "xlsx";

import { motion } from "framer-motion";
import sampleData from "../sampleData.json";

const { Option } = Select;
const { Title, Text } = Typography;

const COLORS = ["#00c9ff", "#92fe9d", "#ff9a9e", "#fbc2eb", "#a1c4fd"];

const InformeInteractivo = () => {
  const [data, setData] = useState([]);
  const [initialLoadComplete, setInitialLoadComplete] = useState(false); // <--- NUEVO ESTADO
  const [rendimientoGlobal, setRendimientoGlobal] = useState(0);
  const [rutaFilter, setRutaFilter] = useState("TODAS"); // 🔹 Nueva variable de filtro
  const [searchText, setSearchText] = useState(""); // 🔹 Texto de búsqueda

  const fechaAnterior = useMemo(() => {
    const ayer = new Date();
    ayer.setDate(ayer.getDate() - 1);
    return ayer.toLocaleDateString("es-CO", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
    });
  }, []);

 // ✅ Leer Excel manualmente 
const handleFileUpload = (e) => {
  const file = e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = (evt) => {
    const bstr = evt.target.result;
    const workbook = XLSX.read(bstr, { type: "binary" });

    // Normalizar clave: minúsculas, sin tildes, sin puntuación, sin espacios sobrantes
    const nk = (key) =>
      key
        .toString()
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/[^\w\s]/gi, "")
        .replace(/\s+/g, " ")
        .trim();

    // Elegir la hoja con más filas útiles que tenga RUTA, VEH y CONDUCTOR
    const requiredNorm = ["ruta", "veh", "conductor"];
    const bestSheet = workbook.SheetNames
      .map((name) => {
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[name], { defval: "", range: 5 });
        const headersNorm = Object.keys(rows[0] || {}).map(nk);
        const hasRequired = requiredNorm.every((h) => headersNorm.includes(h));
        return { name, rows, score: rows.length + (hasRequired ? 1000 : 0) };
      })
      .sort((a, b) => b.score - a.score)[0];

    const jsonData = bestSheet?.rows || [];

    console.log("📄 Hoja seleccionada:", bestSheet?.name, "| Filas:", jsonData.length);
    if (jsonData.length > 0) {
      console.log("📋 Encabezados normalizados:", Object.keys(jsonData[0]).map(nk));
    }

    const toNum = (value) =>
      Number(String(value ?? "").replace(/[^0-9.-]+/g, "")) || 0;

    // fn: buscar primer clave normalizada que coincida con alguno de los candidatos
    const get = (normRow, ...candidates) => {
      for (const c of candidates) {
        const norm = nk(c);
        if (normRow[norm] !== undefined && normRow[norm] !== "") return normRow[norm];
      }
      return "";
    };

    const parsedData = jsonData
      .map((row) => {
        // Construir objeto con claves normalizadas
        const nr = {};
        Object.keys(row).forEach((k) => { nr[nk(k)] = row[k]; });

        return {
          ruta:             String(nr["ruta"] ?? "").trim(),
          veh:              String(nr["veh"] ?? "").trim(),
          conductor:        String(nr["conductor"] ?? "").trim(),
          viajes:           toNum(nr["viajes"]),
          viajesPerdidos:   toNum(get(nr, "viajes perd", "viajes perdidos")),
          usuarios:         toNum(nr["usuarios"]),
          promedioPorViaje: toNum(get(nr, "prom x viaje", "promedio por viaje", "prom xviaje", "promedio viaje")),
          promedioUsuarios: toNum(get(nr, "prom de usuarios", "promedio usuarios", "prom usuarios", "promedio de usuarios")),
          novedades:        String(nr["novedades"] ?? "").trim(),
          valorOperacion:   toNum(get(nr, "valor operacion", "valor operacion")),
          clasificacion:    String(get(nr, "clasific", "clasificacion") ?? "").trim(),
          diferenciaMicroBus: toNum(get(nr, "difer micro bus", "diferencia microbus", "diferencia micro bus")),
        };
      })
      .filter((row) => row.veh && row.veh !== "-" && row.ruta && row.ruta !== "");

    console.log("✅ Registros válidos:", parsedData.length);
    console.log("📊 Muestra:", parsedData.slice(0, 2));

    setData(parsedData);
    setInitialLoadComplete(true);
  };

  reader.readAsBinaryString(file);
};


  // ✅ Calcular rendimiento global
useEffect(() => {
  if (!data || data.length === 0) return setRendimientoGlobal(0);

  const META = 22.2;

  const valores = data
    .filter((record) => record.viajes > 0 && record.usuarios > 0)
    .map((record) => {
      const promViaje = record.usuarios / record.viajes;
      return (promViaje / META) * 100;
    });

  if (valores.length === 0) return setRendimientoGlobal(0);

  const promedio = valores.reduce((a, b) => a + b, 0) / valores.length;
  setRendimientoGlobal(promedio.toFixed(1));
}, [data]);


  // ✅ Filtro de datos (ahora usando `data`)
  const filteredData = useMemo(() => {
    return (Array.isArray(data) ? data : data.rows || []).filter((row) => {
      const matchesRuta = rutaFilter === "TODAS" || row.ruta === rutaFilter;
      const matchesSearch =
        row.conductor.toLowerCase().includes(searchText.toLowerCase()) ||
        String(row.veh).includes(searchText);
      return matchesRuta && matchesSearch;
    });
  }, [data, rutaFilter, searchText]);

  // ✅ Cálculos generales
  const totalUsuarios = filteredData.reduce((sum, r) => sum + (r.usuarios || 0), 0);
  const totalViajes = filteredData.reduce((sum, r) => sum + (r.viajes || 0), 0);
  const promedioGeneral = (totalUsuarios / (totalViajes || 1)).toFixed(2);

  // ✅ Resumen por ruta
  const resumenPorRuta = Object.values(
    filteredData.reduce((acc, row) => {
      if (!acc[row.ruta])
        acc[row.ruta] = { ruta: row.ruta, usuarios: 0, viajes: 0 };
      acc[row.ruta].usuarios += row.usuarios || 0;
      acc[row.ruta].viajes += row.viajes || 0;
      return acc;
    }, {})
  );

  const columns = [
    { title: "Ruta", dataIndex: "ruta", key: "ruta", render: (text) => (
      <span style={{ fontWeight: 600, color: "#003366" }}>
        <BarChartOutlined style={{ color: "#0072ff", marginRight: 6 }} />
        {text}
      </span>
    ), },
    { title: "Clasificación", dataIndex: "clasificacion", key: "clasificacion", render: (c) => (
      <span
        style={{
          color: c === "MICRO" ? "#00b894" : "#0984e3",
          fontWeight: 600,
        }}
      >
        {c}
      </span>
    ), },
    { title: "Vehículo", dataIndex: "veh", key: "veh",  render: (veh) => (
      <span>
        <CarOutlined style={{ color: "#1890ff", marginRight: 6 }} />
        <strong>{veh}</strong>
      </span>
    ), },
    { title: "Conductor", dataIndex: "conductor", key: "conductor", render: (conductor) => (
      <span>
        <UserOutlined style={{ color: "#ff6b6b", marginRight: 6 }} />
        {conductor}
      </span>
    ), },
    { title: "Viajes", dataIndex: "viajes", key: "viajes", render: (viajes) => (
      <span>
        <RiseOutlined style={{ color: "#52c41a", marginRight: 6 }} />
        {viajes}
      </span>
    ), },
    { title: "Viajes Perd.", dataIndex: "viajesPerdidos", key: "viajesPerdidos", render: (v) => (
      <span style={{ color: v > 0 ? "#f5222d" : "#595959" }}>{v}</span>
    ), },
    { title: "Usuarios Movilizados", dataIndex: "usuarios", key: "usuarios", render: (u, record) => {
    const esperado = record.promedioUsuarios || 0;
    const porcentaje = esperado ? (u / esperado) * 100 : 0;

    // Color de la barra según el rendimiento
    let color = "#52c41a"; // verde si supera el promedio
    if (porcentaje < 90) color = "#faad14"; // amarillo si está cerca
    if (porcentaje < 80) color = "#f5222d"; // rojo si está lejos

    
    return (
      <div style={{ width: "150px" }}>
        <span style={{ fontWeight: 500, color }}>
          <TeamOutlined style={{ marginRight: 6 }} />
          {u.toLocaleString("es-CO")}
        </span>
        <Progress
          percent={Math.min(porcentaje, 120)}
          showInfo={false}
          strokeColor={color}
          size={{ height: 10 }}
          style={{ marginTop: 4, transition: "width 1s ease" }}
          title={`${porcentaje.toFixed(1)}% del promedio esperado`}
        />
      </div>
    );
  }, },
    { title: "Prom. x Viaje", dataIndex: "promedioPorViaje", key: "promedioPorViaje",  render: (p, record) => {
    // Cálculo del promedio general
    const totalViajes = filteredData.reduce((sum, r) => sum + r.viajes, 0);
    const totalUsuarios = filteredData.reduce((sum, r) => sum + r.usuarios, 0);
    const promedioGeneral = totalUsuarios / totalViajes || 0;

    // Porcentaje relativo
    const porcentaje = (p / promedioGeneral) * 100;

    // Color dinámico según rendimiento
    let color = "#52c41a"; // verde por defecto
    if (porcentaje < 90) color = "#f5222d";
    else if (porcentaje < 100) color = "#faad14";

    return (
      <div style={{ width: "120px" }}>
        <span style={{ fontWeight: 500, color }}>
          {p.toFixed(1)}
        </span>
        <Progress
          percent={Math.min(porcentaje, 120)}
          showInfo={false}
          strokeColor={color}
          size={{ height: 10 }}
          style={{ marginTop: 4 }}
        />
      </div>
    );
  }, },
    { title: "Prom. Usuarios", dataIndex: "promedioUsuarios", key: "promedioUsuarios", render: (p) => <span style={{ color: "#0a3b1fff" }}>{p}</span>, },
    { title: "Diferencia", dataIndex: "diferenciaUsuarios", key: "diferenciaUsuarios", render: (d) => (
      <span style={{ color: d < 0 ? "#f5222d" : "#52c41a" }}>
        {d > 0 ? "+" : ""}
        {d}
      </span>
    ), },
    
    { title: "Novedades", dataIndex: "novedades", key: "novedades", render: (n) =>
      n ? (
        <span style={{ color: "#fa541c" }}>
          <AlertOutlined style={{ marginRight: 6 }} />
          {n}
        </span>
      ) : (
        <span style={{ color: "#bfbfbf" }}>—</span>
      ), },
    { title: "Valor operación", dataIndex: "valorOperacion", key: "valorOperacion", render: (v) => (
      <span
        style={{
          color: "#16a085",
          fontWeight: 600,
        }}
      >
        <DollarOutlined style={{ marginRight: 6, color: "#27ae60" }} />
        {v.toLocaleString("es-CO")}
      </span>
    ),  },
    { title: "Recaudo Micros", dataIndex: "diferenciaMicroBus", key: "diferenciaMicroBus", render: (v) => (
      <span
        style={{
          color: "#0052cc",
          fontWeight: 600,
        }}
      >
        <FundOutlined style={{ marginRight: 6, color: "#1890ff" }} />
        {v.toLocaleString("es-CO")}
      </span>
    ), },
  
    {
  title: "Rendimiento Total",
  key: "rendimientoTotal",
  render: (_, record) => {
    const META = 21.6;
    const viajes = record.viajes || 0;
    const usuarios = record.usuarios || 0;
    if (viajes === 0) return <span style={{ color: "#bfbfbf" }}>—</span>;

    const promViajeReal = usuarios / viajes;
    const rendimientoTotal = ((promViajeReal / META) * 100).toFixed(1);

    let color = "#52c41a"; // verde ≥100%
    if (rendimientoTotal < 90) color = "#faad14"; // amarillo
    if (rendimientoTotal < 80) color = "#f5222d"; // rojo

    return (
      <div style={{ textAlign: "center" }}>
        <Progress
          type="dashboard"
          percent={Math.min(Number(rendimientoTotal), 120)}
          size={80}
          strokeColor={color}
          format={() => `${rendimientoTotal}%`}
        />
        <div style={{ fontSize: 12, fontWeight: 500, color }}>
          {rendimientoTotal >= 100
            ? "Excelente 🚀"
            : rendimientoTotal >= 90
            ? "Bueno 👍"
            : rendimientoTotal >= 80
            ? "Regular ⚠️"
            : "Bajo ⛔"}
        </div>
      </div>
    );
  },
},


  ];

  const bgGradient =
    rutaFilter === "88VILL"
      ? "linear-gradient(135deg, #00c6ff 0%, #0072ff 100%)"
      : rutaFilter === "87TR"
      ? "linear-gradient(135deg, #43e97b 0%, #38f9d7 100%)"
      : "linear-gradient(135deg, #a1c4fd 0%, #c2e9fb 100%)";

  const fechaActual = new Date().toLocaleDateString("es-CO", {
    day: "2-digit",
    month: "long",
    year: "numeric",
  });

    return (
    <div
      className="min-h-screen p-6"
      style={{
        background: bgGradient,
        transition: "background 0.8s ease",
      }}
    >
      {/* HEADER CORPORATIVO */}
      <motion.div
        initial={{ opacity: 0, y: -40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
        className="mb-6"
      >
        <div
          style={{
            borderRadius: "20px",
            background: "rgba(255,255,255,0.95)",
            boxShadow: "0 8px 30px rgba(0,0,0,0.15)",
            padding: "20px 30px",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            backdropFilter: "blur(10px)",
          }}
        >
          <div style={{ display: "flex", alignItems: "center" }}>
            <img
              src={require("../assets/logo promedio.jpg")}
              alt="Logo Cootranspinal"
              style={{
                width: 150,
                height: "auto",
                marginRight: 20,
                borderRadius: "12px",
                boxShadow: "0 4px 10px rgba(0,0,0,0.15)",
                transition: "transform 0.3s ease",
              }}
              onMouseOver={(e) =>
                (e.currentTarget.style.transform = "scale(1.05)")
              }
              onMouseOut={(e) =>
                (e.currentTarget.style.transform = "scale(1)")
              }
            />
            <div>
              <Title level={3} style={{ margin: 0, color: "#003366" }}>
                Cootranspinal
              </Title>
              <Text type="secondary" style={{ fontSize: "14px" }}>
                Cooperativa Multiactiva de Transportadores El Pinal
              </Text>
            </div>
          </div>
          <div>
            <Text strong style={{ color: "#003366", fontSize: "16px" }}>
              Informe del {fechaAnterior}
            </Text>
          </div>
        </div>

        {/* Línea inferior animada */}
        <motion.div
          style={{
            height: "5px",
            marginTop: "8px",
            borderRadius: "5px",
            background:
              rutaFilter === "88VILL"
                ? "linear-gradient(90deg, #0072ff 0%, #00c6ff 100%)"
                : rutaFilter === "87TR"
                ? "linear-gradient(90deg, #43e97b 0%, #38f9d7 100%)"
                : "linear-gradient(90deg, #a1c4fd 0%, #c2e9fb 100%)",
          }}
          animate={{
            width: ["0%", "100%"],
          }}
          transition={{
            duration: 1.5,
            ease: "easeInOut",
            repeat: Infinity,
            repeatType: "reverse",
          }}
        />
      </motion.div>

      {/* CONTENIDO PRINCIPAL */}
      <motion.div
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
      >
        <Card
          style={{
            borderRadius: "20px",
            backdropFilter: "blur(10px)",
            background: "rgba(255, 255, 255, 0.9)",
            boxShadow: "0 8px 30px rgba(0,0,0,0.15)",
          }}
          bordered={false}
        >
          <div style={{ textAlign: "center", marginBottom: "20px" }}>
  <input
    type="file"
    accept=".xls,.xlsx,.xlsm"
    onChange={handleFileUpload}
    style={{
      marginTop: "10px",
      padding: "8px",
      border: "1px solid #ccc",
      borderRadius: "10px",
      cursor: "pointer",
    }}
  />
  <p style={{ color: "#003366", fontWeight: 500, marginTop: 5 }}>
    📂 Cargar archivo Excel (IMP.xlsm)
  </p>
</div>

          <Title level={3} className="text-center" style={{ color: "#003366" }}>
            📊 Informe Interactivo de Operación
          </Title>
          <Text type="secondary" className="block text-center mb-4">
            Resumen general de vehículos, rutas y desempeño diario
          </Text>

          {/* FILTROS */}
          <Row gutter={16} justify="center" className="mb-4">
            <Col xs={24} md={6}>
              <Select
                value={rutaFilter}
                onChange={setRutaFilter}
                style={{ width: "100%" }}
              >
                <Option value="TODAS">Todas las Rutas</Option>
                {[...new Set(data.map((r) => r.ruta))].map((ruta) => (
                  <Option key={ruta} value={ruta}>
                    {ruta}
                  </Option>
                ))}
              </Select>
            </Col>
            <Col xs={24} md={6}>
              <Input
                placeholder="Buscar conductor o vehículo..."
                value={searchText}
                onChange={(e) => setSearchText(e.target.value)}
              />
            </Col>
          </Row>

          {/* TARJETAS RESUMEN */}
          <Row gutter={[16, 16]} justify="center" className="mb-6">
            {[
              { title: "Total Viajes", value: totalViajes, color: "#00c9ff" },
              { title: "Total Usuarios", value: totalUsuarios, color: "#82ca9d" },
              { title: "Promedio General", value: promedioGeneral, color: "#ff9a9e" },
            ].map((item, i) => (
              <Col xs={24} md={8} key={i}>
                <motion.div whileHover={{ scale: 1.05 }}>
                  <Card
                    bordered={false}
                    style={{
                      borderRadius: "18px",
                      background: `linear-gradient(135deg, ${item.color} 0%, #ffffff 100%)`,
                      textAlign: "center",
                      boxShadow: "0 6px 15px rgba(228, 225, 225, 0.66)",
                    }}
                  >
                    <Statistic
                      title={<span style={{ color: "#003366" }}>{item.title}</span>}
                      value={item.value}
                      valueStyle={{ color: "#003366" }}
                    />
                  </Card>
                </motion.div>
              </Col>
            ))}
          </Row>

          <Divider style={{ borderColor: "#ccc" }} />

          {/* TARJETA DE RENDIMIENTO GLOBAL */}
          <Row gutter={16} style={{ marginBottom: 20 }}>
            <Col span={24}>
              <Card
                style={{
                  borderRadius: 20,
                  background:
                    "linear-gradient(135deg, #0f2027, #58cbf1, #031922)",
                  color: "white",
                  textAlign: "center",
                  boxShadow: "0 4px 15px rgba(252, 251, 251, 0.76)",
                  transform: "scale(1)",
                  transition: "all 0.3s ease-in-out",
                }}
                onMouseOver={(e) =>
                  (e.currentTarget.style.transform = "scale(1.02)")
                }
                onMouseOut={(e) =>
                  (e.currentTarget.style.transform = "scale(1)")
                }
              >
                <h2
                  style={{
                    color: "#fff",
                    marginBottom: 10,
                    fontSize: "1.5rem",
                  }}
                >
                  Rendimiento General del Día 🚍
                </h2>

                <Progress
                  type="dashboard"
                  percent={rendimientoGlobal}
                  size={150}
                  strokeColor={
                    rendimientoGlobal >= 100
                      ? "#52c41a"
                      : rendimientoGlobal >= 90
                      ? "#faad14"
                      : "#f5222d"
                  }
                  format={() => `${rendimientoGlobal}%`}
                />

                <div
                  style={{
                    fontSize: "1.2rem",
                    marginTop: 10,
                    color:
                      rendimientoGlobal >= 100
                        ? "#53862b"
                        : rendimientoGlobal >= 90
                        ? "#ebba19"
                        : "#6d120a",
                  }}
                >
                  {rendimientoGlobal >= 100
                    ? "Excelente rendimiento 🚀"
                    : rendimientoGlobal >= 90
                    ? "Buen rendimiento 👍"
                    : "Rendimiento bajo ⛔"}
                </div>
              </Card>
            </Col>
          </Row>

          {/* TABLA PRINCIPAL */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8 }}
          >
            <Title
              level={4}
              style={{
                textAlign: "center",
                color:
                  rutaFilter === "88VILL"
                    ? "#0072ff"
                    : rutaFilter === "87TR"
                    ? "#43e97b"
                    : "#003366",
                marginBottom: "20px",
                textShadow: "0 1px 3px rgba(255, 255, 255, 0.89)",
              }}
            >
              📋 Informe Detallado
            </Title>

            <Table
  dataSource={filteredData}
  columns={columns}
              rowKey={(record) => `${record.ruta}-${record.veh}-${record.conductor}`}
  pagination={false}
  bordered={false}
  size="middle"
  style={{
    borderRadius: "16px",
    overflow: "hidden",
    background: "rgba(255,255,255,0.98)",
    boxShadow: "0 8px 25px rgba(0,0,0,0.08)",
    transition: "all 0.3s ease-in-out",
  }}
  rowClassName={(record) => {
    // Color dinámico según el rendimiento del vehículo
    const usuarios = record.usuarios || 0;
    const esperado = record.promedioUsuarios || 0;
    const porcentaje = esperado ? (usuarios / esperado) * 100 : 0;

    if (porcentaje >= 100) return "fila-alta";
    if (porcentaje >= 85) return "fila-media";
    return "fila-baja";
  }}

            />
          </motion.div>
         {/* BLOQUE DE VISUALIZACIÓN ACTUALIZADO */}
<Divider
  style={{
    borderColor: "#ccc",
    marginTop: 50,
    marginBottom: 30,
    fontSize: "18px",
    color: "#003366",
  }}
>
  📈 Visualización de Desempeño
</Divider>

<motion.div
  initial={{ opacity: 0 }}
  animate={{ opacity: 1 }}
  transition={{ duration: 1.2 }}
>
  <Row gutter={[24, 24]}>
{/* 🏆 RANKING MOTIVACIONAL CONDUCTORES DESTACADOS */}
<Col xs={24} md={14}>
  <motion.div whileHover={{ scale: 1.02 }} transition={{ duration: 0.3 }}>
    <Card
      title={
        <span style={{ color: "#003366", fontWeight: 600 }}>
          <BarChartOutlined style={{ color: "#f1c40f", marginRight: 8 }} />
          Ranking - Promedio por Viaje
        </span>
      }
      bordered={false}
      style={{
        borderRadius: 20,
        background: "linear-gradient(135deg, #9dd4fdff 0%, #f7faff 100%)",
        boxShadow: "0 8px 25px rgba(0,0,0,0.08)",
      }}
    >
      <ResponsiveContainer width="100%" height={420}>
        <BarChart
          data={[...filteredData]
            .sort((a, b) => b.promedioPorViaje - a.promedioPorViaje)
            .slice(0, 10)}
          margin={{ top: 40, right: 30, left: 20, bottom: 40 }}
          barCategoryGap="35%"
        >
          <XAxis
            dataKey="veh"
            tickFormatter={(veh, index) => {
              const item = [...filteredData]
                .sort((a, b) => b.promedioPorViaje - a.promedioPorViaje)
                .slice(0, 10)[index];
              return item ? `${veh}\n${item.conductor.split(" ")[0]}` : veh;
            }}
            tick={{
              fontSize: 13,
              fill: "#003366",
              fontWeight: 600,
            }}
            tickMargin={25}
            height={80}
            angle={-20}
            textAnchor="end"
            interval={0}
          />
          <YAxis />
          <Tooltip
            contentStyle={{
              background: "rgba(255,255,255,0.95)",
              borderRadius: 10,
              boxShadow: "0 2px 10px rgba(0,0,0,0.15)",
            }}
            formatter={(value, name, entry) => [
              `${value.toFixed(1)} usuarios/viaje`,
              `${entry.payload.conductor}`,
            ]}
            labelFormatter={(veh) => `Vehículo ${veh}`}
          />

          {/* Sin leyenda */}
          <Bar
            dataKey="promedioPorViaje"
            radius={[10, 10, 0, 0]}
            barSize={45}
          >
            {[...filteredData]
              .sort((a, b) => b.promedioPorViaje - a.promedioPorViaje)
              .slice(0, 10)
              .map((entry, index) => {
                // 🎨 Colores para top 3 (oro, plata, bronce)
                if (index === 0) return <Cell key={index} fill="#ffcc00" />;
                if (index === 1) return <Cell key={index} fill="#a0a0a0" />;
                if (index === 2) return <Cell key={index} fill="#cd7f32" />;

                // 🔵 Gradiente azul progresivo del 4° al 10°
                const shades = [
                  "#003366",
                  "#0a4275",
                  "#14538c",
                  "#1f65a3",
                  "#2a77ba",
                  "#3599d9",
                  "#40b0ff",
                ];
                return <Cell key={index} fill={shades[index - 3] || "#003366"} />;
              })}
          </Bar>
        </BarChart>
      </ResponsiveContainer>

      {/* 🏆 Cuadros motivacionales solo para los 3 primeros */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-around",
          marginTop: 25,
          flexWrap: "wrap",
          gap: "20px",
        }}
      >
        {[...filteredData]
          .sort((a, b) => b.promedioPorViaje - a.promedioPorViaje)
          .slice(0, 3)
          .map((item, index) => (
            <motion.div
              key={index}
              animate={{
                scale: [1, 1.05, 1],
                boxShadow:
                  index === 0
                    ? ["0 0 10px #ffd700", "0 0 25px #ffd700", "0 0 10px #ffd700"]
                    : index === 1
                    ? ["0 0 8px #dcdcdc", "0 0 15px #dcdcdc", "0 0 8px #dcdcdc"]
                    : ["0 0 6px #b36c26", "0 0 12px #b36c26", "0 0 6px #b36c26"],
              }}
              transition={{ duration: 2, repeat: Infinity }}
              style={{
                textAlign: "center",
                borderRadius: 15,
                background:
                  index === 0
                    ? "linear-gradient(145deg, #fff5b0, #ffe76b)"
                    : index === 1
                    ? "linear-gradient(145deg, #f1f1f1, #dcdcdc)"
                    : "linear-gradient(145deg, #f6c88f, #cd7f32)",
                padding: "15px 20px",
                width: 130,
                color: "#003366",
                fontWeight: 600,
                position: "relative",
              }}
            >
              {index === 0 && (
                <span
                  style={{
                    position: "absolute",
                    top: -25,
                    left: "50%",
                    transform: "translateX(-50%)",
                    fontSize: "1.8rem",
                  }}
                >
                  👑
                </span>
              )}
              <div style={{ fontSize: "1rem" }}>Veh {item.veh}</div>
              <div style={{ fontSize: "0.9rem", marginTop: 4 }}>
                {item.conductor.split(" ")[0]}
              </div>
              <div style={{ fontSize: "0.8rem", color: "#555", marginTop: 3 }}>
                {item.promedioPorViaje.toFixed(1)} u/viaje
              </div>
            </motion.div>
          ))}
      </div>

      <div
        style={{
          textAlign: "center",
          marginTop: 25,
          fontWeight: 600,
          color: "#032241ff",
          fontSize: "1rem",
        }}
      >
        🏅 Reconocimiento a los 3 conductores con mejor promedio por viaje
      </div>
    </Card>
  </motion.div>
</Col>




  {/* 🥧 GRÁFICO DE TORTA MEJORADO */}
{/* 🥧 GRÁFICO DE TORTA MEJORADO CON RUTA DESTACADA */}
<Col xs={24} md={10}>
  <motion.div whileHover={{ scale: 1.03 }} transition={{ duration: 0.4 }}>
    <Card
      title={
        <span style={{ color: "#003366", fontWeight: 600 }}>
          <FundOutlined style={{ color: "#115346ff", marginRight: 8 }} />
          Distribución de Usuarios por Ruta
        </span>
      }
      bordered={false}
      style={{
        borderRadius: 20,
        background: "linear-gradient(135deg, #9dd4fdff 0%, #ffffff 100%)",
        boxShadow: "0 8px 25px rgba(0,0,0,0.08)",
        transition: "all 0.3s ease-in-out",
      }}
    >
      <ResponsiveContainer width="100%" height={380}>
        <PieChart>
          <defs>
            {/* 💡 Efecto de brillo animado */}
            <radialGradient id="shine" cx="50%" cy="50%" r="70%">
              <stop offset="0%" stopColor="rgba(248, 248, 248, 0.9)" />
              <stop offset="100%" stopColor="rgba(230, 213, 213, 0)" />
            </radialGradient>
          </defs>

          <Pie
            data={resumenPorRuta}
            dataKey="usuarios"
            nameKey="ruta"
            cx="50%"
            cy="50%"
            innerRadius={70}
            outerRadius={120}
            paddingAngle={3}
            startAngle={90}
            endAngle={-270}
            isAnimationActive={true}
            animationBegin={200}
            animationDuration={1200}
            animationEasing="ease-out"
            labelLine={false}
            label={({ name, percent }) =>
              `${name}: ${(percent * 100).toFixed(1)}%`
            }
          >
            {(() => {
              const maxUsuarios = Math.max(
                ...resumenPorRuta.map((r) => r.usuarios)
              );
              return resumenPorRuta.map((entry, index) => {
                const isTop = entry.usuarios === maxUsuarios;
                const baseColors = [
                  "#0072ff",
                  "#00c3ff",
                  "#00e0b8",
                  "#009e73",
                  "#f4b400",
                  "#ff7043",
                  "#a569bd",
                  "#17a2b8",
                ];
                const fillColor = isTop
                  ? "url(#shine)"
                  : baseColors[index % baseColors.length];

                return (
                  <Cell
                    key={`cell-${index}`}
                    fill={fillColor}
                    stroke={isTop ? "#ffd700" : "#fffdfdff"}
                    strokeWidth={isTop ? 4 : 2}
                    style={{
                      filter: isTop
                        ? "drop-shadow(0px 0px 10px rgba(233, 232, 228, 0.8))"
                        : "none",
                      transition: "all 0.5s ease",
                    }}
                  />
                );
              });
            })()}
          </Pie>

          {/* Tooltip elegante */}
          <Tooltip
            contentStyle={{
              background: "rgba(255,255,255,0.95)",
              borderRadius: 12,
              boxShadow: "0 4px 10px rgba(0,0,0,0.15)",
            }}
            formatter={(value, name) => [
              `${value.toLocaleString()} usuarios`,
              `Ruta ${name}`,
            ]}
          />

          {/* Leyenda */}
          <Legend
            layout="vertical"
            align="right"
            verticalAlign="middle"
            iconType="circle"
            wrapperStyle={{
              paddingLeft: "20px",
              fontSize: "0.85rem",
              color: "#003366",
            }}
          />
        </PieChart>
      </ResponsiveContainer>

      {/* Texto inferior */}
      <div
        style={{
          textAlign: "center",
          marginTop: 20,
          fontWeight: 600,
          color: "#003366",
          fontSize: "1rem",
        }}
      >
        Total usuarios movilizados:{" "}
        <span style={{ color: "#0072ff" }}>
          {resumenPorRuta
            .reduce((sum, r) => sum + r.usuarios, 0)
            .toLocaleString()}
        </span>
        <br />
        🥇 Ruta líder:{" "}
        <span style={{ color: "#ffbc02ff" }}>
          {(resumenPorRuta.reduce(
    (prev, current) =>
      prev.usuarios > current.usuarios ? prev : current,
    { usuarios: 0, ruta: "No hay rutas" } // valor inicial
  )).ruta}  
        </span>
      </div>
    </Card>
  </motion.div>
</Col>


  </Row>
</motion.div>
  </Card>
</motion.div>
</div>
  );
};


export default InformeInteractivo;
